/* compare abs(x) and abs(y) */
static int
ucmp(mpz_t *y, mpz_t *x)
{
  size_t i;
  for (i=imax(x->sz,y->sz)-1;;i--) {
    if (dg(y,i) < dg(x,i))
      return (-1);
    else if (dg(y,i) > dg(x,i))
      return 1;
    if (i == 0) break;
  }
  return 0;
}

static int
uzero(mpz_t *x)
{
  for (size_t i=0; i < x->sz; i++)
    if ((x->p)[i] != 0)
      return 0;
  return 1;
}

